"use client"; import {useState} from "react";
export default function Wallet(){const[asset,setAsset]=useState("NGN");const[address,setAddress]=useState("");const[saved,setSaved]=useState(false);return <main className="container section"><h1>Company payment wallet</h1><p className="muted">Configure the destination shown to customers for investment-payment instructions.</p><div className="card form" style={{margin:"25px 0"}}><label className="label">Asset / currency</label><input className="input" value={asset} onChange={e=>setAsset(e.target.value)}/><label className="label">Wallet / payment address</label><input className="input" value={address} onChange={e=>setAddress(e.target.value)} placeholder="Enter approved company destination"/><label className="label">QR code image URL</label><input className="input" placeholder="Secure hosted QR image URL"/><button className="btn btn-primary" onClick={()=>setSaved(true)}>Save wallet settings</button>{saved&&<div className="notice" style={{marginTop:15}}>Saved in the demo interface. Production persistence must use authenticated admin APIs.</div>}</div></main>}